INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(129495, 'ruRU', '', 'Постарайся не шуметь. Эти звери на нервах.', 24330),
(129496, 'ruRU', '', 'Что говорят на улицах, $n?', 24330),
(129497, 'ruRU', '', 'Какие-нибудь новости, $n?', 24330),
(129498, 'ruRU', '', 'Мы тут становимся довольно беспокойными. Есть новости о том, что происходит?', 24330),
(129500, 'ruRU', '', 'Эй, $n! Совет выпустил какую-нибудь новую информацию?', 24330),
(129501, 'ruRU', '', 'В эти дни не только небеса полны магии! Расслабься и взгляни на некоторых наших новейших питомцев.', 24330),
(129505, 'ruRU', '', 'Наши крылья затмят ваше небо!', 24330),
(129506, 'ruRU', '', 'Ваши небеса принадлежат Легиону!', 24330),
(129507, 'ruRU', '', 'Я использую твой труп, чтобы накормить своих подопечных.', 24330),
(129508, 'ruRU', '', 'Если ты думаешь, что я выпущу Камень Рока из виду, ты страшно ошибаешься. Приступим.', 24330),
(129512, 'ruRU', '', 'Пытаешься заставить землю Азерота воевать с самой собой? Глупый эредар!', 24330),
(129513, 'ruRU', '', 'Знаешь, если бы ты просто использовал Камень Рока, это бы скоро закончилось.', 24330),
(129514, 'ruRU', '', 'Какой смысл владеть таким могущественным артефактом, если боишься его использовать? Камень Рока был бы куда полезнее в моих руках.', 24330),
(129515, 'ruRU', '', 'У демонов есть свой огонь скверны, поэтому они полагают, что могут управлять и огнём Азерота. Ох, как же они ошибаются!', 24330),
(129516, 'ruRU', '', 'Силы воды обычно восстанавливающие, самый пассивный и слабый из элементов. Что Легион вообразил с ней сделать?', 24330),
(129517, 'ruRU', '', 'Подумай о величии земли... такой крепкой, защищающей, неизменной. И всё же, когда она лишь содрогается, способна на такое грандиозное разрушение.', 24330),
(129518, 'ruRU', '', 'Слышишь ли ты ветер, дитя? Он вопит о помощи, о спасении от Легиона.', 24330),
(129519, 'ruRU', '', 'Даже в плену мой Мрачный Тотем остаётся готовым к бою. А вот твоё Кольцо Земли... слабое.', 24330),
(129526, 'ruRU', '', 'Я полностью доверяю нашим лидерам. Нам не стоит сбиваться с пути из-за праздной болтовни по всему городу. Люди справляются по-разному.', 24330),
(129527, 'ruRU', '', 'Нам стоит стараться сохранять позитивный настрой. Людям и без того хватает забот. Нужно подавать пример остальным.', 24330),
(129528, 'ruRU', '', 'Проходя раньше по улицам, я чувствовал, как мои уши устают от всех этих домыслов. Столько неопределённости здесь в последнее время.', 24330),
(129529, 'ruRU', '', 'Интересно, когда улицы успокоятся. Город гудит с самого начала всего этого.', 24330),
(129554, 'ruRU', '', 'Порча будет очищена!', 24330),
(129556, 'ruRU', '', 'Эта тварь разоряет не только твой народ, но и саму землю! Если и был повод использовать Камень Рока, то именно сейчас!', 24330),
(129572, 'ruRU', '', 'Такая сила... такой хаос!', 24330),
(129573, 'ruRU', '', 'Соберись, дитя! Что с тобой такое?', 24330),
(129575, 'ruRU', '', 'Вот так! Поддайся силе!', 24330),
(129580, 'ruRU', '', 'Слушай - мы уверены, что наши товары "в безопасности" здесь, но зачем рисковать?', 24330),
(129581, 'ruRU', '', 'А тебе какое дело?', 24330),
(129582, 'ruRU', '', 'Ты никогда не видал, как кто-то охраняет своё добро? Проходи дальше!', 24330),
(129583, 'ruRU', '', 'Не дёргайся! Не хотим же мы, чтоб наше добро рассыпалось, а?', 24330),
(129584, 'ruRU', '', 'Что надо, чтоб тут хоть кто помог? Мы надеялись переправить своё добро домой, в безопасность, до того как... ну, сам знаешь.', 24330),
(129585, 'ruRU', '', 'Конец света? Пф! Я тут пытаюсь вывезти наше бабло, а эти ребята ползут как улитки!', 24330),
(129586, 'ruRU', '', 'Ох, надеюсь, наш тайник дома выдержит конец света.', 24330),
(129655, 'ruRU', '', 'Возвращайся позже. У меня может найтись для тебя другое задание.', 24330),
(129663, 'ruRU', '', 'Ох, не волнуйся, провидец... мы будем следить за Камнем Рока.', 24330),
(129695, 'ruRU', '', 'Эти наглые эредары до сих пор думают, что могут подчинить землю Азерота своей воле? Накажи их!', 24330),
(129696, 'ruRU', '', 'И вот они возвращаются в землю.', 24330),
(129697, 'ruRU', '', 'Спасибо тебе, незнакомец! Эти бесы появились из ниоткуда! У меня осталось немного, но ты заслуживаешь награды. Осмотри наши припасы и возьми всё, что нужно.', 24330),
(129698, 'ruRU', '', 'Мой дорогой Кориан... что я буду делать без тебя?', 24330);
